import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const router = express.Router();
const upload = multer({ storage: multer.memoryStorage() });

interface AnalysisResult {
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  totalKeywordsChecked: number;
}

router.post('/api/scan-resume', upload.single('resume'), async (req: Request, res: Response) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'No resume PDF uploaded.' });
    }

    const jobDescription = req.body.jobDescription;
    if (!jobDescription) {
      return res.status(400).json({ error: 'Job description is required.' });
    }

    const pdfData = await pdfParse(req.file.buffer);
    const resumeText = pdfData.text.toLowerCase();

    // Simple keyword extraction from job description (alphanumeric tokens > 3 chars)
    const stopWords = new Set(['and', 'the', 'for', 'with', 'you', 'that', 'this', 'from', 'our', 'are']);
    const rawKeywords = jobDescription.toLowerCase().match(/\b[a-z]{4,}\b/g) || [];
    const uniqueKeywords = Array.from(new Set(rawKeywords)).filter(kw => !stopWords.has(kw));

    const matchedKeywords: string[] = [];
    const missingKeywords: string[] = [];

    uniqueKeywords.forEach(keyword => {
      if (resumeText.includes(keyword)) {
        matchedKeywords.push(keyword);
      } else {
        missingKeywords.push(keyword);
      }
    });

    const matchScore = uniqueKeywords.length > 0 
      ? Math.round((matchedKeywords.length / uniqueKeywords.length) * 100)
      : 0;

    const result: AnalysisResult = {
      matchScore,
      matchedKeywords,
      missingKeywords,
      totalKeywordsChecked: uniqueKeywords.length
    };

    return res.json(result);
  } catch (error) {
    console.error('Error parsing PDF or analyzing resume:', error);
    return res.status(500).json({ error: 'Internal server error during resume parsing.' });
  }
});

export default router;

import React, { useState } from 'react';

interface ScanResult {
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  totalKeywordsChecked: number;
}

export const TailwindMatchScoreDashboard: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [jobDescription, setJobDescription] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [result, setResult] = useState<ScanResult | null>(null);

  const handleScan = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file || !jobDescription) return;

    setLoading(true);
    const formData = new FormData();
    formData.append('resume', file);
    formData.append('jobDescription', jobDescription);

    try {
      const response = await fetch('/api/scan-resume', {
        method: 'POST',
        body: formData,
      });
      const data = await response.json();
      setResult(data);
    } catch (err) {
      console.error('Scan failed:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6 bg-slate-900 text-slate-100 rounded-xl shadow-2xl">
      <h1 className="text-3xl font-extrabold mb-6 text-indigo-400">AI Resume Keyword Scanner</h1>

      <form onSubmit={handleScan} className="space-y-6">
        <div>
          <label className="block text-sm font-medium mb-2">Job Description</label>
          <textarea
            rows={5}
            className="w-full p-3 bg-slate-800 border border-slate-700 rounded-lg focus:ring-2 focus:ring-indigo-500 text-sm"
            placeholder="Paste target job description here..."
            value={jobDescription}
            onChange={(e) => setJobDescription(e.target.value)}
          />
        </div>

        <div>
          <label className="block text-sm font-medium mb-2">Upload Resume (PDF)</label>
          <input
            type="file"
            accept=".pdf"
            onChange={(e) => setFile(e.target.files?.[0] || null)}
            className="block w-full text-sm text-slate-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-indigo-600 file:text-white hover:file:bg-indigo-700"
          />
        </div>

        <button
          type="submit"
          disabled={loading || !file || !jobDescription}
          className="w-full py-3 px-4 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-700 font-semibold rounded-lg transition-all shadow-md"
        >
          {loading ? 'Analyzing Resume...' : 'Scan & Calculate Match Score'}
        </button>
      </form>

      {result && (
        <div className="mt-10 grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="flex flex-col items-center justify-center p-6 bg-slate-800 rounded-xl border border-slate-700">
            <span className="text-sm text-slate-400 mb-2">Match Score</span>
            <div className="text-5xl font-black text-indigo-400">{result.matchScore}%</div>
            <div className="w-full bg-slate-700 rounded-full h-2.5 mt-4 overflow-hidden">
              <div className="bg-indigo-500 h-2.5 rounded-full transition-all duration-1000" style={{ width: `${result.matchScore}%` }} />
            </div>
          </div>

          <div className="p-6 bg-slate-800 rounded-xl border border-slate-700">
            <h3 className="font-bold text-emerald-400 mb-3">Matched Keywords ({result.matchedKeywords.length})</h3>
            <div className="flex flex-wrap gap-2">
              {result.matchedKeywords.map((kw, i) => (
                <span key={i} className="px-2.5 py-1 bg-emerald-950 border border-emerald-800 text-emerald-300 text-xs rounded-md">
                  {kw}
                </span>
              ))}
            </div>
          </div>

          <div className="p-6 bg-slate-800 rounded-xl border border-slate-700">
            <h3 className="font-bold text-rose-400 mb-3">Missing Keywords ({result.missingKeywords.length})</h3>
            <div className="flex flex-wrap gap-2">
              {result.missingKeywords.map((kw, i) => (
                <span key={i} className="px-2.5 py-1 bg-rose-950 border border-rose-800 text-rose-300 text-xs rounded-md">
                  {kw}
                </span>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
